      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n전국거주자) 급급급)8/6~14)약 5~10분 메가커피 아이스 아메리카노 기프티콘) 온라인설문) 70대 남녀 어르신\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.07. 10:30\n조회 22\n구독\n전국거주자) 급급급)8/6~14)약 5~10분 메가커피 아이스 아메리카노 기프티콘) 온라인설문) 70대 남녀 어르신\n몇분께서 여러번 신청하신 관계로 추가모집이 필요합니다\n신청하신분은 재신청 안하셔도 됩니다\n모집인원이 마감되면 고유링크가 열리지 않는다고 하오니 착오 없으시기 바랍니다\n■ 참여 대상\n· 부모님 장례에서 상주를 맡으셨던 분\n· 빈소 계약, 장례식장 선정, 절차 진행 등을 직접 결정하고 진행하신 분\n※ 본 설문은 상주 경험이 있으신 분만 참여하실 수 있습니다. 가족 중 다른 분이 전담하셔서 옆에서 도움만 주신 경우, 또는 조문객으로 참석하신 경우는 대상에서 제외됩니다.\n※ 설문 첫 문항에서 상주 여부를 확인하며, 해당하지 않으실 경우 설문이 자동 종료됩니다.\n■ 진행 안내\n· 소요 시간: 약 5~10분\n· 참여 인원: 선착순 100명 (많은 참여 부탁드립니다)\n· 참여 기간: [08월 06일 ~ 08월 14일]\n■ 경품 안내\n성실하게 답변해주신 분들 100분께 메가커피 아이스 아메리카노 기프티콘을 드립니다.\n· 지급 방법: 설문에 기재해주신 휴대폰 번호로 기프티콘 발송\n· 지급 시기: 당첨자 발표 후 [8월31일] 이내\n※ 응답이 지나치게 부실하거나 무성의한 경우, 중복 참여로 확인되는 경우에는 추첨 대상에서 제외될 수 있는 점 양해 부탁드립니다.\n※ 당첨자에게는 별도 안내 없이 기프티콘이 발송되며, 휴대폰 번호가 잘못 기재된 경우 재발송이 어려울 수 있습니다.\n폼 주소\n고유링크 :\n마감합니다 감사합니다\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n전국거주자) 급급급)8/6~14)약 5~10분 메가커피 아이스 아메리카노 기프티콘) 온라인설문) 80대이상 남녀 어르신\n좌담회알바좌담회카페\n26.08.07.\n댓글\n0\n전국거주자) 급급급)8/6~14)약 5~10분 메가커피 아이스 아메리카노 기프티콘) 온라인설문) 70대 남녀 어르신\n좌담회알바좌담회카페\n26.08.07.\n댓글\n0\n전국거주자) 급급급)8/6~14)약 5~10분 메가커피 아이스 아메리카노 기프티콘) 온라인설문) 60대 남녀\n좌담회알바좌담회카페\n26.08.07.\n댓글\n0\n전국거주자) 급급급)8/6~14)약 5~10분 메가커피 아이스 아메리카노 기프티콘) 온라인설문) 50대 남녀\n좌담회알바좌담회카페\n26.08.07.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
