      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n8/18~28,9월초) 만 20세~45세 여성) 두피케어 관련 유치조사&좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.07. 15:05\n조회 135\n구독\n8/18~28,9월초) 만 20세~45세 여성) 두피케어 관련 유치조사&좌담회\n일정변경으로 재신청 가능합니다\n*조사 조건\n*만 20세~45세 여성\n*평소 두피 건강에 관심 많은 여성분(두피 케어 제품을 사용/비사용 상관없음)\n*조사 방법 : 두피케어 두가지 제품을 사용 평가 후 일부 좌담회\n제품유치날짜 8월 18일(화)~8월 28일(금)예상\n제품사용 두가지제품 각4일씩 사용(이틀 휴지기)\n좌담회 날짜 9월초 예상 / 시간은 추후 안내드립니다\n유치 조사 사례비 35,000원\n좌담회 사례비 50,000원\n좌담회 장소 신용산역 부근\n*신청 하실때 이 방법으로 보내주세요\n이름/연락처/성별/생년월일/만나이/거주지역(동까지)/직업(직장명/학교명 기재) 이메일 주소/\n현재 고민하고 있는 두피 증상(모두)/현재모발길이/두피고민해결을 위한 케어 방법(1~2년이내)_없으면\"없음\"\n예시1)\n홍길녀/010-1111-1234/여/931026/33세/마포구 공덕동/직장인(00어학원)/gggg@naver.com\n두피 건조함. 각질, 두피 가려움/중단발머리/두피전용삼푸,두피팩,두피전용 디바이스사용\n예시2)\n이제니/010-2222-1234/여/031026/25세/숙명여대 경영학과 4년/gggg@naver.com/각질,비듬/커트머리/두피전용샴푸,두피스크럽,두피에센스,외부케어 관리샵\nhttps://forms.gle/SPGxVb4cm6g3knBCA\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.07. 20:21 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n만 25~59세 남성) 8/14(금)에 있을 식품 관련 조사\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n8/18~28,9월초) 만 20세~45세 여성) 두피케어 관련 유치조사&좌담회\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n8/22) 만 19~39세 여성) 평화.통일 정책 토론회\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n8/22) 만 19~39세 남성) 평화.통일 정책 토론회\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
