      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n8/13) 음료 관련 설문조사 - 중/고등학생\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.07. 16:41\n조회 53\n구독\n8/13) 음료 관련 설문조사 - 중/고등학생\n일정 및 조건, 자세한 사항은 다음과 같습니다.\n신청 시 필수 기재 사항 정확히 작성 부탁 드립니다~\n※ 사전 설문 발송 예정입니다.\n■ 조건 및 구성\n- 만 13-18세 중/고등학생\n- 월 1회 이상 과일 맛 탄산음료를 사 먹는 학생(일반, 제로 무관)\n■ 조사 일정 : 약 1시간 30분 내\n일정\n시간\n08월 13일(목)\n17시00분\n■ 조사 방법 : ai 챗봇 가이드에 따라 채팅형 설문조사 진행 =관련해서 확정시 안내드립니다\n■ PAY\n- 참석 사례비 : 35,000원\n■ 신청 시 필수 기재사항\n이름 / 성별 / 연락처 / 연령(생년월일) / 거주지(구,동)/직업(학교,학년) / 최근 1개월 내 구매 및 음용한 과일 맛 탄산음료 브랜드(예 : 환'타, 탐스 등) / 주로 음용하는 과일 맛 탄산음료 브랜드\nhttps://forms.gle/QfBkzp5TFnfxJHpH8\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.07. 20:17 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n(3일간 파워포인트 온라인과제 + 2시간 일대일 온라인 인터뷰 ) 부모님과 함께 사는 고급 유제품 음용자 만40세~만55세 남녀 (사례비 13만원)\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n8/13) 음료 관련 설문조사 - 중/고등학생\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n8/27~28) 만25-39세 여성 립케어 제품테스트 설문조사\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n8/20~25) 만 30~40대 여성 (1977~1996년생) 차(티백) 소비자 좌담회\n좌담회알바좌담회카페\n26.08.07.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
