      "raw_content": "여성 패션 쇼핑 조사-서울 및 수도권 거주 만23~54세 여성[5만원]\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해 신청 시스템이 개선되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n​\n대상 : 서울 및 수도권 거주 만 23세 - 54세 여성\n본인이 사용할 목적으로 럭셔리/명품 브랜드의 가방•핸드백을 구매해 사용하고 계신 분,\n또는 현재나 향후 구매를 고려하고 계신 분\n럭셔리/명품에 대한 기준은 개인마다 다르므로 브랜드 사용 경험을 특정 브랜드에 제한하지 않으며,\n백화점 외에 다양한 경로(구제샵, 명품중고매장, SNS 등)를 통해 구매하신 경우도 모두 해당됩니다.\n일정 : 추후 안내\n방법 : 평소 이용하는 오프라인 매장 또는 온라인 채널에서 연구원과 함께 쇼핑 후 소감을 나누는 조사\n소요시간 : 최대 3시간\n사례비 : 5만원\n장소 : 참여자께서 평소 주로 이용하시는 매장\n​\n조사 방법 안내\n1. 평소 오프라인 매장(백화점, 구제샵 등)에서 쇼핑하신다면, 평소처럼 프로젝트 연구원과 함께\n가방/핸드백 매장을 방문합니다. 좋아하는 브랜드 매장에 가보고, 마음에 드는 아이템이 있으면 착용도\n해보며, 지인과 쇼핑하듯 편안하게 이 시간을 즐겨 주시면 됩니다.\n2. 만약 평소 온라인에서 주로 쇼핑하신다면, 주로 이용하는 온라인 채널을 연구원과 함께 둘러보는 방식으로\n진행합니다.\n3. 쇼핑 후에는 어떠했는지 소감을 함께 나누는 시간을 갖습니다.\n매장 상황과 대기 시간을 고려하여 최대 3시간을 예상하고 있습니다.\n4. 장소는 참여자께서 평소 주로 이용하시는 매장입니다.\n5. 조사 전, 현재 소장하고 계신 가방/핸드백 사진을 연구원에게 사전에 공유해 주셔야 합니다.\n​\n신청하기",
